package org.brightstats.report;
import java.util.*;import java.util.zip.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import com.google.gson.*;
/** Only reviewed in-memory entries are packaged. Never traverses a workspace or home directory. */
public final class ReproducibilityBundle {
 private ReproducibilityBundle(){}
 public record Options(boolean includeProjectData,boolean includeReport){}
 public record Entry(String name,byte[] bytes){public Entry{if(!name.matches("[A-Za-z0-9][A-Za-z0-9._-]*"))throw new IllegalArgumentException("Flat bundle entry required");bytes=bytes.clone();}@Override public byte[] bytes(){return bytes.clone();}}
 public record Plan(List<Entry> entries,List<String> cautions){public Plan{entries=List.copyOf(entries);cautions=List.copyOf(cautions);}}
 private static final Gson JSON=new GsonBuilder().setPrettyPrinting().serializeNulls().create();
 public static Plan preview(JsonObject project,JsonObject report,Options options){Objects.requireNonNull(project);Objects.requireNonNull(options);if(options.includeReport()&&!options.includeProjectData())throw new IllegalArgumentException("Reports contain source data and case-level outputs; enable source-data inclusion explicitly first.");List<Entry> entries=new ArrayList<>();List<String> warnings=new ArrayList<>();JsonObject settings=project.deepCopy();for(String key:List.of("observations","dataPreparation","derivation"))settings.remove(key);add(entries,"analysis-settings.json",settings);warnings.add("Settings include column/construct names, model parameters, seeds, and possibly case/group membership or user-entered text. Review every included JSON entry before sharing.");if(options.includeProjectData()){add(entries,"project.json",project);warnings.add("Source data enabled: project includes working observations, original import cells/history and any project derivation metadata. These may identify people or local source paths.");}if(options.includeReport()){if(report==null)throw new IllegalArgumentException("No complete report is available.");add(entries,"analysis.bsreport.json",report);warnings.add("The complete report includes its own historical source project, settings, case-level outputs, predictive samples or chains; these can differ from the current working project.");}JsonObject environment=new JsonObject();environment.addProperty("applicationVersion",org.brightstats.cli.Main.VERSION);environment.addProperty("javaVersion",System.getProperty("java.version"));environment.addProperty("javaVendor",System.getProperty("java.vendor"));environment.addProperty("os",System.getProperty("os.name"));environment.addProperty("architecture",System.getProperty("os.arch"));environment.add("applicationCodeIdentity",codeHash());environment.addProperty("workingSourceFrameSha256",sourceFrame(project));add(entries,"runtime.json",environment);for(var entry:entries){String text=new String(entry.bytes(),StandardCharsets.UTF_8);if(text.matches("(?is).*\\b(password|passphrase|secret|token|api[_-]?key)\\b.*"))warnings.add(entry.name()+": credential-like words found; inspect values. This is a heuristic, not a secrecy guarantee.");if(text.matches("(?s).*(?:[A-Za-z]:\\\\\\\\|/(?:home|Users)/).*"))warnings.add(entry.name()+": possible local filesystem path found; inspect before sharing.");}String readme="Bright-Stats reproducibility bundle\n\nThis is a data/settings archive, not an executable installer. It installs or runs nothing.\nVerify every file against manifest.json using SHA-256 before use.\nOpen project.json via Open project when included; open analysis.bsreport.json via Open report.\nSettings-only bundles require you to supply the original data and recreate the relevant model.\nUse the named analysis with the saved settings and seeds. Runtime/application code hashes identify this build, but do not guarantee identical floating-point results on every machine.\nNo automatic execution, downloaded programs, credentials store, or home-directory archive is included. User-entered text/data can nevertheless be sensitive.\n";entries.add(new Entry("README.txt",readme.getBytes(StandardCharsets.UTF_8)));long total=entries.stream().mapToLong(e->e.bytes.length).sum();if(total>64L*1024*1024)throw new IllegalArgumentException("Bundle exceeds the 64 MiB in-memory review limit.");return new Plan(entries,warnings);}
 private static void add(List<Entry> entries,String name,JsonElement value){byte[] bytes=JSON.toJson(value).getBytes(StandardCharsets.UTF_8);if(bytes.length>16L*1024*1024)throw new IllegalArgumentException(name+" exceeds the 16 MiB entry limit.");entries.add(new Entry(name,bytes));}
 public static String sha256(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception impossible){throw new IllegalStateException(impossible);}}
 private static JsonObject codeHash(){JsonObject identity=new JsonObject();try{var location=Path.of(org.brightstats.cli.Main.class.getProtectionDomain().getCodeSource().getLocation().toURI());if(Files.isRegularFile(location)){identity.addProperty("kind","application-jar-sha256");identity.addProperty("sha256",sha256(Files.readAllBytes(location)));}else{try(var input=org.brightstats.cli.Main.class.getResourceAsStream("Main.class")){identity.addProperty("kind","development-main-class-only-sha256");identity.addProperty("sha256",input==null?"unavailable":sha256(input.readAllBytes()));}}}catch(Exception unavailable){identity.addProperty("kind","unavailable");}return identity;}
 private static String sourceFrame(JsonObject project){JsonObject source=new JsonObject();for(String key:List.of("columnNames","observations","dataPreparation","derivation"))if(project.has(key))source.add(key,project.get(key));return org.brightstats.stats.AnalysisIdentity.json(source);}
 public static JsonObject manifest(Plan plan){JsonObject manifest=new JsonObject();manifest.addProperty("format","bright-stats-reproducibility-bundle");manifest.addProperty("formatVersion",1);JsonArray entries=new JsonArray();for(Entry entry:plan.entries()){JsonObject item=new JsonObject();item.addProperty("name",entry.name());item.addProperty("bytes",entry.bytes.length);item.addProperty("sha256",sha256(entry.bytes));entries.add(item);}manifest.add("entries",entries);manifest.add("privacyCautions",JSON.toJsonTree(plan.cautions()));return manifest;}
 public static void write(Path destination,Plan reviewed)throws Exception{if(Files.exists(destination))throw new FileAlreadyExistsException(destination.toString());Path parent=destination.toAbsolutePath().getParent();Path temporary=Files.createTempFile(parent,".bright-stats-bundle-",".tmp");try{try(var zip=new ZipOutputStream(Files.newOutputStream(temporary))){List<Entry> entries=new ArrayList<>(reviewed.entries());entries.add(new Entry("manifest.json",JSON.toJson(manifest(reviewed)).getBytes(StandardCharsets.UTF_8)));Set<String> names=new HashSet<>();for(Entry entry:entries){if(!names.add(entry.name()))throw new IllegalArgumentException("Duplicate bundle entry");ZipEntry item=new ZipEntry(entry.name());item.setTime(0);zip.putNextEntry(item);zip.write(entry.bytes);zip.closeEntry();}}Files.move(temporary,destination);}finally{Files.deleteIfExists(temporary);}}
}
